nodes-of-edge-list.code:
export function nodesOfEdgeList(edges: [string, string][]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];
  for (const [from, to] of edges) {
    if (!seen.has(from)) {
      seen.add(from);
      result.push(from);
    }
    if (!seen.has(to)) {
      seen.add(to);
      result.push(to);
    }
  }
  return result;
}

adjacency-from-edges.code:
export function adjacencyFromEdges(edges: [string, string][]): Map<string, Set<string>> {
  const adj = new Map<string, Set<string>>();
  for (const [from, to] of edges) {
    if (!adj.has(from)) adj.set(from, new Set<string>());
    if (!adj.has(to)) adj.set(to, new Set<string>());
    adj.get(from)!.add(to);
  }
  return adj;
}

bytes-to-base64.code:
export function bytesToBase64(bytes: number[]): string {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  let out = "";
  let i = 0;
  while (i < bytes.length) {
    const b0 = bytes[i] & 0xff;
    const hasB1 = i + 1 < bytes.length;
    const hasB2 = i + 2 < bytes.length;
    const b1 = hasB1 ? bytes[i + 1] & 0xff : 0;
    const b2 = hasB2 ? bytes[i + 2] & 0xff : 0;
    const triple = (b0 << 16) | (b1 << 8) | b2;

    out += alphabet[(triple >> 18) & 0x3f];
    out += alphabet[(triple >> 12) & 0x3f];
    out += hasB1 ? alphabet[(triple >> 6) & 0x3f] : "=";
    out += hasB2 ? alphabet[triple & 0x3f] : "=";

    i += 3;
  }
  return out;
}

is-real-calendar-date.code:
export function isRealCalendarDate(year: number, month: number, day: number): boolean {
  if (!Number.isInteger(year) || !Number.isInteger(month) || !Number.isInteger(day)) {
    return false;
  }
  if (month < 0 || month > 11) {
    return false;
  }
  if (day < 1) {
    return false;
  }

  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

  return day <= daysInMonth[month];
}

