base64-encode-byte-range.code:
export function base64EncodeByteRange(bytes: number[], start: number, end: number): string {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  let out = "";
  for (let i = start; i < end; i += 3) {
    const b0 = bytes[i] & 0xff;
    const b1 = bytes[i + 1] & 0xff;
    const b2 = bytes[i + 2] & 0xff;
    const n = (b0 << 16) | (b1 << 8) | b2;
    out += alphabet[(n >> 18) & 0x3f];
    out += alphabet[(n >> 12) & 0x3f];
    out += alphabet[(n >> 6) & 0x3f];
    out += alphabet[n & 0x3f];
  }
  return out;
}

int24-to-base64-chars.code:
const BASE64_ALPHABET =
  "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

export function int24ToBase64Chars(value: number): string {
  const v = value & 0xffffff;
  return (
    BASE64_ALPHABET[(v >>> 18) & 63] +
    BASE64_ALPHABET[(v >>> 12) & 63] +
    BASE64_ALPHABET[(v >>> 6) & 63] +
    BASE64_ALPHABET[v & 63]
  );
}

zero-pad-number.code:
export function zeroPadNumber(value: number, width: number): string {
  const negative = value < 0;
  const digits = String(Math.abs(value));
  const padded = digits.length >= width ? digits : "0".repeat(width - digits.length) + digits;
  return negative ? "-" + padded : padded;
}

duration-to-ms.code:
export function durationToMs(text: string): number | undefined {
  const units = new Map<string, number>([
    ["ms", 1],
    ["msec", 1],
    ["msecs", 1],
    ["millisecond", 1],
    ["milliseconds", 1],
    ["s", 1000],
    ["sec", 1000],
    ["secs", 1000],
    ["second", 1000],
    ["seconds", 1000],
    ["m", 60_000],
    ["min", 60_000],
    ["mins", 60_000],
    ["minute", 60_000],
    ["minutes", 60_000],
    ["h", 3_600_000],
    ["hr", 3_600_000],
    ["hrs", 3_600_000],
    ["hour", 3_600_000],
    ["hours", 3_600_000],
    ["d", 86_400_000],
    ["day", 86_400_000],
    ["days", 86_400_000],
    ["w", 604_800_000],
    ["week", 604_800_000],
    ["weeks", 604_800_000],
  ]);

  const match = /^\s*(\d+(?:\.\d+)?|\.\d+)\s*([a-zA-Z]+)\s*$/.exec(text);
  if (!match) {
    return undefined;
  }

  const value = Number(match[1]);
  const factor = units.get(match[2].toLowerCase());
  if (factor === undefined || !Number.isFinite(value)) {
    return undefined;
  }

  return value * factor;
}

order-by-dependencies.code:
export function orderByDependencies(nodes: string[], edges: [string, string][]): string[] {
  const indegree = new Map<string, number>();
  const adjacency = new Map<string, string[]>();

  for (const node of nodes) {
    if (!indegree.has(node)) {
      indegree.set(node, 0);
      adjacency.set(node, []);
    }
  }

  for (const [from, to] of edges) {
    if (!indegree.has(from) || !indegree.has(to)) {
      throw new Error(`Edge references unknown node: [${from}, ${to}]`);
    }
    adjacency.get(from)!.push(to);
    indegree.set(to, indegree.get(to)! + 1);
  }

  // Seed the queue with zero-indegree nodes in input order for stable results.
  const queue: string[] = [];
  for (const node of indegree.keys()) {
    if (indegree.get(node) === 0) queue.push(node);
  }

  const result: string[] = [];
  let head = 0;
  while (head < queue.length) {
    const node = queue[head++];
    result.push(node);
    for (const next of adjacency.get(node)!) {
      const remaining = indegree.get(next)! - 1;
      indegree.set(next, remaining);
      if (remaining === 0) queue.push(next);
    }
  }

  if (result.length !== indegree.size) {
    throw new Error("Cycle detected in dependency edges");
  }

  return result;
}

