export function datePlusDays(date: Date, days: number): Date {
  const result = new Date(date.getTime());
  result.setUTCDate(result.getUTCDate() + days);
  return result;
}

ms-to-short-duration.code:
export function msToShortDuration(ms: number): string {
  const SECOND = 1000;
  const MINUTE = 60 * SECOND;
  const HOUR = 60 * MINUTE;
  const DAY = 24 * HOUR;

  if (Math.abs(ms) < SECOND) {
    return `${Math.round(ms)}ms`;
  }

  const units: Array<[number, string]> = [
    [DAY, "d"],
    [HOUR, "h"],
    [MINUTE, "m"],
    [SECOND, "s"],
  ];

  for (const [size, label] of units) {
    const rounded = Math.round(ms / size);
    if (Math.abs(rounded) >= 1) {
      return `${rounded}${label}`;
    }
  }

  return `${Math.round(ms)}ms`;
}

split-json-pointer.code:
export function splitJsonPointer(pointer: string): string[] {
  if (pointer === "") {
    return [""];
  }
  if (!pointer.startsWith("/")) {
    throw new Error(`Invalid JSON Pointer: must start with "/" or be empty, got "${pointer}"`);
  }
  return pointer.split("/");
}

cache-function-results.code:
export function cacheFunctionResults<A, R>(fn: (arg: A) => R): (arg: A) => R {
  const cache = new Map<A, R>();

  return (arg: A): R => {
    if (cache.has(arg)) {
      return cache.get(arg) as R;
    }
    const result = fn(arg);
    cache.set(arg, result);
    return result;
  };
}

parse-iso-date.code:
export function parseIsoDate(text: string): Date {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text);
  if (!m) return new Date(NaN);

  const year = Number(m[1]);
  const month = Number(m[2]);
  const day = Number(m[3]);

  if (month < 1 || month > 12 || day < 1) return new Date(NaN);

  // setUTCFullYear avoids Date.UTC's mapping of years 0-99 to 1900-1999.
  const d = new Date(0);
  d.setUTCFullYear(year, month - 1, day);
  d.setUTCHours(0, 0, 0, 0);

  // Reject days that overflowed into the next month (e.g. Feb 29 in a non-leap year).
  if (
    d.getUTCFullYear() !== year ||
    d.getUTCMonth() !== month - 1 ||
    d.getUTCDate() !== day
  ) {
    return new Date(NaN);
  }

  return d;
}

