export function unescapePointerToken(token: string): string {
  return token.replace(/~[01]/g, (match) => (match === "~1" ? "/" : "~"));
}

value-at-json-pointer.code:
export function valueAtJsonPointer(doc: object, pointer: string): unknown {
  if (pointer === "") {
    return doc;
  }
  if (!pointer.startsWith("/")) {
    return undefined;
  }

  const tokens = pointer
    .slice(1)
    .split("/")
    .map((token) => token.replace(/~1/g, "/").replace(/~0/g, "~"));

  let current: unknown = doc;

  for (const token of tokens) {
    if (Array.isArray(current)) {
      if (!/^(0|[1-9]\d*)$/.test(token)) {
        return undefined;
      }
      const index = Number(token);
      if (index >= current.length) {
        return undefined;
      }
      current = current[index];
    } else if (typeof current === "object" && current !== null) {
      if (!Object.prototype.hasOwnProperty.call(current, token)) {
        return undefined;
      }
      current = (current as Record<string, unknown>)[token];
    } else {
      return undefined;
    }
  }

  return current;
}

compare-version-core.code:
export function compareVersionCore(a: string, b: string): -1 | 0 | 1 {
  const parse = (v: string): [number, number, number] => {
    let core = v.trim();
    const plus = core.indexOf("+");
    if (plus !== -1) core = core.slice(0, plus);
    const dash = core.indexOf("-");
    if (dash !== -1) core = core.slice(0, dash);
    if (core.startsWith("v") || core.startsWith("V")) core = core.slice(1);

    const parts = core.split(".");
    const nums: number[] = [];
    for (let i = 0; i < 3; i++) {
      const n = parseInt(parts[i] ?? "0", 10);
      nums.push(Number.isNaN(n) ? 0 : n);
    }
    return [nums[0], nums[1], nums[2]];
  };

  const pa = parse(a);
  const pb = parse(b);

  for (let i = 0; i < 3; i++) {
    if (pa[i] < pb[i]) return -1;
    if (pa[i] > pb[i]) return 1;
  }
  return 0;
}

bounded-recent-cache.code:
export function boundedRecentCache(capacity: number = 100): {
  get(key: unknown): unknown;
  set(key: unknown, value: unknown): void;
  has(key: unknown): boolean;
  delete(key: unknown): boolean;
  clear(): void;
  readonly size: number;
} {
  if (!Number.isInteger(capacity) || capacity < 1) {
    throw new RangeError("capacity must be a positive integer");
  }

  // Map preserves insertion order: first key = least recently used,
  // last key = most recently used.
  const store = new Map<unknown, unknown>();

  return {
    get(key: unknown): unknown {
      if (!store.has(key)) return undefined;
      const value = store.get(key);
      // Refresh recency by moving the entry to the end.
      store.delete(key);
      store.set(key, value);
      return value;
    },

    set(key: unknown, value: unknown): void {
      if (store.has(key)) {
        store.delete(key);
      } else if (store.size >= capacity) {
        // Evict the least recently used entry (first in iteration order).
        const oldest = store.keys().next().value;
        store.delete(oldest);
      }
      store.set(key, value);
    },

    has(key: unknown): boolean {
      return store.has(key);
    },

    delete(key: unknown): boolean {
      return store.delete(key);
    },

    clear(): void {
      store.clear();
    },

    get size(): number {
      return store.size;
    },
  };
}

edit-count-between-strings.code:
export function editCountBetweenStrings(a: string, b: string): number {
  // Ensure b is the shorter string to minimize memory usage
  let s = a;
  let t = b;
  if (t.length > s.length) {
    s = b;
    t = a;
  }
  const n = s.length;
  const m = t.length;
  if (m === 0) return n;

  let prev: number[] = new Array(m + 1);
  let curr: number[] = new Array(m + 1);
  for (let j = 0; j <= m; j++) prev[j] = j;

  for (let i = 1; i <= n; i++) {
    curr[0] = i;
    const sc = s.charCodeAt(i - 1);
    for (let j = 1; j <= m; j++) {
      const cost = sc === t.charCodeAt(j - 1) ? 0 : 1;
      const del = prev[j] + 1;
      const ins = curr[j - 1] + 1;
      const sub = prev[j - 1] + cost;
      let best = del < ins ? del : ins;
      if (sub < best) best = sub;
      curr[j] = best;
    }
    const tmp = prev;
    prev = curr;
    curr = tmp;
  }
  return prev[m];
}

compare-prerelease-identifiers.code:
export function comparePrereleaseIdentifiers(a: string, b: string): -1 | 0 | 1 {
  const isNumeric = (s: string): boolean => /^[0-9]+$/.test(s);

  const aNum = isNumeric(a);
  const bNum = isNumeric(b);

  if (aNum && bNum) {
    // Strip leading zeros (keeping at least one digit), then compare
    // by length and lexicographically to avoid precision loss on large numbers.
    const x = a.replace(/^0+(?=\d)/, "");
    const y = b.replace(/^0+(?=\d)/, "");
    if (x.length !== y.length) return x.length < y.length ? -1 : 1;
    if (x === y) return 0;
    return x < y ? -1 : 1;
  }

  // Numeric identifiers rank below alphanumeric identifiers.
  if (aNum) return -1;
  if (bNum) return 1;

  // Both alphanumeric: compare as text.
  if (a === b) return 0;
  return a < b ? -1 : 1;
}

nearest-string.code:
export function nearestString(word: string, candidates: string[]): string {
  const levenshtein = (a: string, b: string): number => {
    if (a === b) return 0;
    if (a.length === 0) return b.length;
    if (b.length === 0) return a.length;

    let prev: number[] = new Array(b.length + 1);
    let curr: number[] = new Array(b.length + 1);
    for (let j = 0; j <= b.length; j++) prev[j] = j;

    for (let i = 1; i <= a.length; i++) {
      curr[0] = i;
      for (let j = 1; j <= b.length; j++) {
        const cost = a[i - 1] === b[j - 1] ? 0 : 1;
        curr[j] = Math.min(
          prev[j] + 1,
          curr[j - 1] + 1,
          prev[j - 1] + cost
        );
      }
      [prev, curr] = [curr, prev];
    }
    return prev[b.length];
  };

  let best = "";
  let bestDist = Infinity;
  for (const candidate of candidates) {
    const d = levenshtein(word, candidate);
    if (d < bestDist) {
      bestDist = d;
      best = candidate;
    }
  }
  return best;
}

is-uuid.code:
export function isUuid(text: string): boolean {
  const rfcUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
  const nilUuid = /^0{8}-0{4}-0{4}-0{4}-0{12}$/;
  const maxUuid = /^[fF]{8}-[fF]{4}-[fF]{4}-[fF]{4}-[fF]{12}$/;
  return rfcUuid.test(text) || nilUuid.test(text) || maxUuid.test(text);
}

bytes-to-uuid-text.code:
export function bytesToUuidText(bytes: Uint8Array): string {
  let hex = "";
  for (let i = 0; i < bytes.length; i++) {
    hex += bytes[i].toString(16).padStart(2, "0");
  }
  return (
    hex.slice(0, 8) + "-" +
    hex.slice(8, 12) + "-" +
    hex.slice(12, 16) + "-" +
    hex.slice(16, 20) + "-" +
    hex.slice(20, 32)
  );
}

uuid-version-number.code:
export function uuidVersionNumber(uuid: string): number {
  const pattern = /^[0-9a-f]{8}-[0-9a-f]{4}-([0-9a-f])[0-9a-f]{3}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  const match = pattern.exec(uuid);
  if (match === null) {
    throw new Error(`Not a valid UUID: ${uuid}`);
  }
  return parseInt(match[1], 16);
}

uuid-to-bytes.code:
export function uuidToBytes(uuid: string): Uint8Array {
  const pattern =
    /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
  if (typeof uuid !== "string" || !pattern.test(uuid)) {
    throw new TypeError(`Invalid UUID: ${String(uuid)}`);
  }
  const hex = uuid.replace(/-/g, "");
  const out = new Uint8Array(16);
  for (let i = 0; i < 16; i++) {
    out[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  }
  return out;
}

bump-semver.code:
export function bumpSemver(version: string, release: string): string {
  const match = /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$/.exec(version);
  if (!match) {
    throw new Error(`Invalid semantic version: ${version}`);
  }

  let major = Number(match[1]);
  let minor = Number(match[2]);
  let patch = Number(match[3]);

  switch (release) {
    case "major":
      major += 1;
      minor = 0;
      patch = 0;
      break;
    case "minor":
      minor += 1;
      patch = 0;
      break;
    case "patch":
      patch += 1;
      break;
    default:
      throw new Error(`Invalid release type: ${release}`);
  }

  return `${major}.${minor}.${patch}`;
}

