escape-html.code:
export function escapeHtml(text: string): string {
  const entities: Record<string, string> = {
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;",
  };
  return text.replace(/[&<>"']/g, (ch) => entities[ch]);
}

compare-version-prerelease.code:
export function compareVersionPrerelease(a: string, b: string): -1 | 0 | 1 {
  const parsePrerelease = (version: string): string[] | null => {
    const withoutBuild = version.split("+")[0];
    const dash = withoutBuild.indexOf("-");
    if (dash === -1) return null;
    const pre = withoutBuild.slice(dash + 1);
    if (pre === "") return null;
    return pre.split(".");
  };

  const isNumeric = (id: string): boolean => /^\d+$/.test(id);

  const compareIdentifiers = (x: string, y: string): -1 | 0 | 1 => {
    const xNum = isNumeric(x);
    const yNum = isNumeric(y);

    if (xNum && yNum) {
      const xs = x.replace(/^0+(?=\d)/, "");
      const ys = y.replace(/^0+(?=\d)/, "");
      if (xs.length !== ys.length) return xs.length < ys.length ? -1 : 1;
      if (xs === ys) return 0;
      return xs < ys ? -1 : 1;
    }

    // Numeric identifiers have lower precedence than alphanumeric ones.
    if (xNum) return -1;
    if (yNum) return 1;

    if (x === y) return 0;
    return x < y ? -1 : 1;
  };

  const pa = parsePrerelease(a);
  const pb = parsePrerelease(b);

  // No pre-release ranks higher than any pre-release.
  if (pa === null && pb === null) return 0;
  if (pa === null) return 1;
  if (pb === null) return -1;

  const len = Math.min(pa.length, pb.length);
  for (let i = 0; i < len; i++) {
    const c = compareIdentifiers(pa[i], pb[i]);
    if (c !== 0) return c;
  }

  // Shared identifiers are equal: the shorter list ranks lower.
  if (pa.length === pb.length) return 0;
  return pa.length < pb.length ? -1 : 1;
}

is-email.code:
export function isEmail(text: string): boolean {
  if (typeof text !== "string") return false;
  if (text.length > 254) return false;

  const at = text.lastIndexOf("@");
  if (at < 1 || at === text.length - 1) return false;

  const local = text.slice(0, at);
  const domain = text.slice(at + 1);

  if (local.length > 64) return false;

  // Local part: letters, digits, and common special characters, dot-separated
  // with no leading, trailing, or consecutive dots.
  const localPattern = /^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*$/;
  if (!localPattern.test(local)) return false;

  // Domain: at least two labels, each alphanumeric with optional inner hyphens,
  // and a final alphabetic TLD of at least two letters.
  const labels = domain.split(".");
  if (labels.length < 2) return false;

  const labelPattern = /^[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$/;
  for (const label of labels) {
    if (label.length === 0 || label.length > 63) return false;
    if (!labelPattern.test(label)) return false;
  }

  const tld = labels[labels.length - 1];
  if (!/^[A-Za-z]{2,}$/.test(tld)) return false;

  return true;
}

normalize-semver.code:
export function normalizeSemver(version: string): string | null {
  const re =
    /^\s*=?\s*v?\s*(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(-(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*)?(\+[0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*)?\s*$/;

  const m = re.exec(version);
  if (m === null) {
    return null;
  }

  const major = m[1];
  const minor = m[2];
  const patch = m[3];
  const pre = m[4] ?? "";
  const build = m[5] ?? "";

  return `${major}.${minor}.${patch}${pre}${build}`;
}

version-difference-kind.code:
export function versionDifferenceKind(a: string, b: string): string | null {
  const pattern =
    /^v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$/;

  const parse = (v: string) => {
    const m = pattern.exec(v.trim());
    if (!m) {
      throw new TypeError(`Invalid semantic version: ${v}`);
    }
    return {
      major: m[1],
      minor: m[2],
      patch: m[3],
      prerelease: m[4] ?? null,
      build: m[5] ?? null,
    };
  };

  const x = parse(a);
  const y = parse(b);

  // Numeric identifiers are compared by value; leading zeros are already
  // excluded by the grammar, so string equality is numeric equality.
  if (x.major !== y.major) return "major";
  if (x.minor !== y.minor) return "minor";
  if (x.patch !== y.patch) return "patch";
  if (x.prerelease !== y.prerelease) return "prerelease";
  if (x.build !== y.build) return "build";
  return null;
}

