export function sortVersionsDescending(versions: string[]): string[] {
  interface Parsed {
    core: number[];
    pre: string[] | null;
  }

  const parse = (v: string): Parsed => {
    let s = v.trim();
    if (s[0] === "v" || s[0] === "V") s = s.slice(1);
    const plus = s.indexOf("+");
    if (plus !== -1) s = s.slice(0, plus);
    const dash = s.indexOf("-");
    const corePart = dash === -1 ? s : s.slice(0, dash);
    const prePart = dash === -1 ? null : s.slice(dash + 1);
    const core = corePart.split(".").map((p) => {
      const n = parseInt(p, 10);
      return Number.isNaN(n) ? 0 : n;
    });
    while (core.length < 3) core.push(0);
    const pre = prePart === null || prePart === "" ? null : prePart.split(".");
    return { core, pre };
  };

  const isNumeric = (s: string) => /^\d+$/.test(s);

  const comparePre = (a: string[], b: string[]): number => {
    const len = Math.min(a.length, b.length);
    for (let i = 0; i < len; i++) {
      const x = a[i];
      const y = b[i];
      const xn = isNumeric(x);
      const yn = isNumeric(y);
      if (xn && yn) {
        const d = parseInt(x, 10) - parseInt(y, 10);
        if (d !== 0) return d < 0 ? -1 : 1;
      } else if (xn !== yn) {
        return xn ? -1 : 1; // numeric identifiers have lower precedence
      } else if (x !== y) {
        return x < y ? -1 : 1;
      }
    }
    if (a.length === b.length) return 0;
    return a.length < b.length ? -1 : 1;
  };

  const compare = (a: Parsed, b: Parsed): number => {
    const len = Math.max(a.core.length, b.core.length);
    for (let i = 0; i < len; i++) {
      const d = (a.core[i] ?? 0) - (b.core[i] ?? 0);
      if (d !== 0) return d < 0 ? -1 : 1;
    }
    if (a.pre === null && b.pre === null) return 0;
    if (a.pre === null) return 1;
    if (b.pre === null) return -1;
    return comparePre(a.pre, b.pre);
  };

  return versions
    .map((v) => ({ original: v, parsed: parse(v) }))
    .sort((x, y) => compare(y.parsed, x.parsed))
    .map((e) => e.original);
}

