export function coerceToNumber(value: unknown): number {
  if (typeof value === "number") {
    return value;
  }

  if (typeof value === "bigint") {
    return Number(value);
  }

  if (typeof value === "boolean") {
    return value ? 1 : 0;
  }

  if (value === null) {
    return 0;
  }

  if (value === undefined) {
    return NaN;
  }

  if (typeof value === "string") {
    const s = value.trim();
    if (s === "") {
      return NaN;
    }
    const hex = /^([+-])?0x([0-9a-f]+)$/i.exec(s);
    if (hex) {
      const magnitude = parseInt(hex[2], 16);
      return hex[1] === "-" ? -magnitude : magnitude;
    }
    return Number(s);
  }

  if (value instanceof Date) {
    return value.getTime();
  }

  if (typeof value === "object") {
    const tagged = value as Record<string, unknown>;
    if ("$type" in tagged && tagged["$type"] === "undefined") {
      return NaN;
    }
    if ("$date" in tagged) {
      const d = new Date(tagged["$date"] as string | number);
      return d.getTime();
    }
  }

  return NaN;
}

