export function gen2(data: number[], offset: number): { word: number; offp: number } {
  const len = data.length;
  if (len === 0) {
    return { word: 0, offp: offset };
  }
  let word = 0;
  let j = offset % len;
  for (let i = 0; i < 4; i++) {
    word = (word << 8) | (data[j] & 0xff);
    j = (j + 1) % len;
  }
  return { word: word | 0, offp: j };
}

