export function gen11(items: any[], edges: [any, any][]): any[] {
  const index = new Map<any, number>();
  items.forEach((value, i) => {
    if (!index.has(value)) index.set(value, i);
  });

  const n = items.length;
  const adj: number[][] = Array.from({ length: n }, () => []);
  const indeg: number[] = new Array(n).fill(0);

  for (const [before, after] of edges) {
    if (!index.has(before) || !index.has(after)) {
      throw new Error("Edge references an item not in the list");
    }
    const u = index.get(before)!;
    const v = index.get(after)!;
    adj[u].push(v);
    indeg[v]++;
  }

  const queue: number[] = [];
  for (let i = 0; i < n; i++) {
    if (indeg[i] === 0) queue.push(i);
  }

  const order: number[] = [];
  let head = 0;
  while (head < queue.length) {
    const u = queue[head++];
    order.push(u);
    for (const v of adj[u]) {
      indeg[v]--;
      if (indeg[v] === 0) queue.push(v);
    }
  }

  if (order.length !== n) {
    throw new Error("Cycle detected in ordering constraints");
  }

  return order.map((i) => items[i]);
}

