export function gen37(ms: number): string {
  const sign = ms < 0 ? "-" : "";
  const abs = Math.abs(ms);

  if (abs < 1000) {
    return `${ms} ms`;
  }

  const units: [string, number][] = [
    ["day", 86400000],
    ["hour", 3600000],
    ["minute", 60000],
    ["second", 1000],
  ];

  for (const [name, size] of units) {
    if (abs >= size) {
      const n = Math.round(abs / size);
      return `${sign}${n} ${name}${n === 1 ? "" : "s"}`;
    }
  }

  return `${ms} ms`;
}

