export function gen106(address: string, family: string | undefined): boolean {
  const isIPv4 = (s: string): boolean => {
    const parts = s.split(".");
    if (parts.length !== 4) return false;
    for (const p of parts) {
      if (!/^(0|[1-9]\d{0,2})$/.test(p)) return false;
      if (Number(p) > 255) return false;
    }
    return true;
  };

  const isIPv6 = (input: string): boolean => {
    let s = input;
    const idx = s.lastIndexOf(":");
    if (idx < 0) return false;

    // Handle embedded IPv4 in the final 32 bits.
    const tail = s.slice(idx + 1);
    if (tail.includes(".")) {
      if (!isIPv4(tail)) return false;
      s = s.slice(0, idx + 1) + "0:0";
    }

    const parseGroups = (str: string): string[] | null => {
      if (str === "") return [];
      const groups = str.split(":");
      for (const g of groups) {
        if (!/^[0-9a-fA-F]{1,4}$/.test(g)) return null;
      }
      return groups;
    };

    const compressionCount = s.split("::").length - 1;
    if (compressionCount > 1) return false;

    if (compressionCount === 1) {
      const [left, right] = s.split("::");
      const l = parseGroups(left);
      const r = parseGroups(right);
      if (l === null || r === null) return false;
      return l.length + r.length <= 7;
    }

    const groups = parseGroups(s);
    return groups !== null && groups.length === 8;
  };

  if (family === undefined) {
    return isIPv4(address) || isIPv6(address);
  }
  if (family === "ipv4") {
    return isIPv4(address);
  }
  if (family === "ipv6") {
    return isIPv6(address);
  }
