  const cmpId = (x: string, y: string): number => {
    const xn = isNum(x);
    const yn = isNum(y);
    if (xn && yn) return cmpNumStr(x, y);
    if (xn) return -1;
    if (yn) return 1;
    return x < y ? -1 : x > y ? 1 : 0;
  };

