export function gen165(uuid: string | Uint8Array): string | Uint8Array {
  let hex: string;

  if (typeof uuid === "string") {
    if (!/^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(uuid)) {
      throw new Error("Invalid UUID string");
    }
    hex = uuid.replace(/-/g, "").toLowerCase();
  } else {
    if (!(uuid instanceof Uint8Array) || uuid.length !== 16) {
      throw new Error("Invalid UUID bytes: expected 16 bytes");
    }
    hex = Array.from(uuid, (b) => b.toString(16).padStart(2, "0")).join("");
  }

  // Version nibble is the first digit of the 4th group (index 12).
  if (hex[12] !== "1") {
    throw new Error("Not a version-1 UUID");
  }

  // Timestamp as 15 hex digits: time_hi (12 bits) + time_mid + time_low.
  const ts = hex.slice(13, 16) + hex.slice(8, 12) + hex.slice(0, 8);
  // Version-6 layout: high 12 digits, version nibble, low 3 digits, then clock_seq and node.
  const out = ts.slice(0, 12) + "6" + ts.slice(12, 15) + hex.slice(16);

  if (typeof uuid === "string") {
    return `${out.slice(0, 8)}-${out.slice(8, 12)}-${out.slice(12, 16)}-${out.slice(16, 20)}-${out.slice(20)}`;
  }

  const bytes = new Uint8Array(16);
  for (let i = 0; i < 16; i++) {
    bytes[i] = parseInt(out.slice(i * 2, i * 2 + 2), 16);
  }
  return bytes;
}

