export function gen171(source: any, limit: number | undefined): Array<any> | undefined {
  if (source == null) return undefined;

  const iterFn =
    typeof Symbol !== "undefined" && typeof Symbol.iterator === "symbol"
      ? source[Symbol.iterator]
      : undefined;
  if (typeof iterFn !== "function") return undefined;

  const iterator = iterFn.call(source);
  const max: number =
    typeof limit === "number" && !Number.isNaN(limit) ? limit : Infinity;

  const result: Array<any> = [];

  while (result.length < max) {
    const step = iterator.next();
    if (step.done) return result;
    result.push(step.value);
  }

  // Stopped early: the iterator is not exhausted, so close it.
  if (typeof iterator.return === "function") {
    iterator.return();
  }

  return result;
}
